import {SettingsCenterOwner,SETTINGS_CENTER_OWNER,SETTINGS_CENTER_CONTRACT} from './foundation/global/settings/center.js';
import {SETTINGS_CENTER_GROUPS,SETTINGS_CENTER_SECTION_CATALOG,SETTINGS_CENTER_SECTION_DESCRIPTOR_CONTRACT,defineSettingsFamilySectionDescriptor,editorShortcutSectionFromKeymapDescriptor} from './foundation/global/settings/sections.js';
import {searchSettingsSections,normalizeSettingsSearchText} from './foundation/global/settings/search.js';
import {ScopedPreferencesOwner,SCOPED_PREFERENCES_OWNER} from './foundation/global/preferences/store.js';
import {SemanticCommandBus} from './foundation/global/commands.js';
import {GlobalInputKeymapOwner,createFamilyKeymapDescriptor} from './foundation/global/input-keymap.js';
import {TransientFocusOwner} from './foundation/global/transient-focus.js';
import {createStructuredConsumerAdapter} from './adapters/structured-documents.js';
import {STRUCTURE_TREE,FIXTURES,NOTE_FIXTURES} from './adapters/library-fixtures.js';
import {createEnterpriseAdapter} from './adapters/w03-enterprise.js';

const assert=(condition,message='ASSERTION_FAILED')=>{if(!condition)throw Error(message)};
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const throws=(fn,fragment)=>{let error=null;try{fn()}catch(value){error=value}assert(error&&String(error.message||error).includes(fragment),`EXPECTED_THROW:${fragment}:${error}`)};
const event=key=>({key,prevented:false,stopped:false,preventDefault(){this.prevented=true},stopPropagation(){this.stopped=true}});
class MemoryStorage{constructor(){this.value=null}getItem(){return this.value}setItem(_key,value){this.value=value}}

function fixture({family='structured',surface='library'}={}){
  const storage=new MemoryStorage();
  const preferences=new ScopedPreferencesOwner(storage,{workspace:'W02',surface,view:'main',component:'workspace',family});
  const commands=new SemanticCommandBus();
  commands.register('foundation.settings','WorkspaceHostKernel','Open Settings',()=>({ok:true}),()=>true);
  commands.register('workspace.search','WorkspaceSearchOwner','Search workspace',()=>({ok:true}),()=>true);
  commands.register('structured.bold','StructuredRichContentOwner','Bold',()=>({ok:true}),payload=>payload.family==='structured'||'Structured editor only');
  const keymap=new GlobalInputKeymapOwner({commands,globalBindings:[
    {id:'global.settings',chord:'Ctrl+Comma',commandId:'foundation.settings',allow:true,priority:20},
    {id:'global.search',chord:'Ctrl+K',commandId:'workspace.search',allow:true,priority:10}
  ]});
  const transientFocus=new TransientFocusOwner();
  const owner=new SettingsCenterOwner({preferences,commands,keymap,transientFocus});
  const structuredKeymap=createFamilyKeymapDescriptor({id:'bounded-structured-settings-fixture',family:'structured',semanticOwner:'StructuredCommandAvailabilityOwner',bindings:[
    {id:'editor.bold',chord:'Ctrl+B',commandId:'structured.bold',allow:true,priority:10},
    {id:'editor.indent',chord:'Tab',commandId:'structured.indent',allow:true,priority:5}
  ]});
  const editorDescriptor=editorShortcutSectionFromKeymapDescriptor({keymapDescriptor:structuredKeymap,sourceOwner:'W4E_BoundedStructuredDescriptorFixture'});
  const profile={id:surface,family,capabilities:{structuredEditor:family==='structured'}};
  owner.configurePresentation({profile,familySections:[editorDescriptor]});
  return {storage,preferences,commands,keymap,transientFocus,owner,editorDescriptor,profile};
}

function run(id,fn,tests){try{const evidence=fn();tests.push({id,status:'PASS',evidence:evidence??null})}catch(error){tests.push({id,status:'FAIL',error:String(error?.stack||error)})}}

export function runW4ESettingsCenterTests(){
  const tests=[];
  run('w4e.owner-contract-presentation-only',()=>{const {owner}=fixture();assert(owner.owner===SETTINGS_CENTER_OWNER);assert(SETTINGS_CENTER_CONTRACT.scope==='GLOBAL_PRESENTATION_DISCLOSURE_SEARCH_ONLY');for(const excluded of ['preference-values','preference-persistence','command-semantics','structured-keyboard-semantics','domain-configuration'])assert(SETTINGS_CENTER_CONTRACT.excludes.includes(excluded));assert(SETTINGS_CENTER_CONTRACT.preferenceValueOwner===SCOPED_PREFERENCES_OWNER&&SETTINGS_CENTER_CONTRACT.focusReturnOwner==='TransientFocusOwner')},tests);
  run('w4e.required-groups-structured',()=>{const {owner,profile,editorDescriptor}=fixture(),labels=owner.groups(profile,[editorDescriptor]).map(group=>group.label);assert(same(labels,['Preferences','Settings','Commands','Editor Shortcuts','Shortcuts']),JSON.stringify(labels));return labels},tests);
  run('w4e.non-structured-profile-hides-editor-only',()=>{const {owner,profile,editorDescriptor}=fixture({family:'spatial',surface:'enterprise'}),groups=owner.groups(profile,[editorDescriptor]),labels=groups.map(group=>group.label),sections=groups.flatMap(group=>group.sections.map(section=>section.id));assert(!labels.includes('Editor Shortcuts'));assert(!sections.includes('preferences.editor'));return {labels,sections}},tests);
  run('w4e.family-bound-matching-family-visible',()=>{const {owner}=fixture(),descriptor=defineSettingsFamilySectionDescriptor({id:'settings.structured-family-proof',groupId:'settings',label:'Structured family proof',family:'structured',sourceOwner:'W4E_FamilyApplicabilityFixture',items:[{id:'family-proof',label:'Family proof'}]}),sections=owner.sections({family:'structured',capabilities:{structuredEditor:true}},[descriptor]).map(section=>section.id);assert(sections.includes(descriptor.id));return {profileFamily:'structured',visible:true,sections}},tests);
  run('w4e.family-bound-spatial-hidden',()=>{const {owner}=fixture(),descriptor=defineSettingsFamilySectionDescriptor({id:'settings.structured-family-proof',groupId:'settings',label:'Structured family proof',family:'structured',sourceOwner:'W4E_FamilyApplicabilityFixture',items:[{id:'family-proof',label:'Family proof'}]}),sections=owner.sections({family:'spatial'},[descriptor]).map(section=>section.id);assert(!sections.includes(descriptor.id));return {profileFamily:'spatial',visible:false,sections}},tests);
  run('w4e.family-bound-operational-hidden',()=>{const {owner}=fixture(),descriptor=defineSettingsFamilySectionDescriptor({id:'settings.structured-family-proof',groupId:'settings',label:'Structured family proof',family:'structured',sourceOwner:'W4E_FamilyApplicabilityFixture',items:[{id:'family-proof',label:'Family proof'}]}),sections=owner.sections({family:'operational'},[descriptor]).map(section=>section.id);assert(!sections.includes(descriptor.id));return {profileFamily:'operational',visible:false,sections}},tests);
  run('w4e.family-bound-absent-family-hidden',()=>{const {owner}=fixture(),descriptor=defineSettingsFamilySectionDescriptor({id:'settings.structured-family-proof',groupId:'settings',label:'Structured family proof',family:'structured',sourceOwner:'W4E_FamilyApplicabilityFixture',items:[{id:'family-proof',label:'Family proof'}]}),sections=owner.sections({},[descriptor]).map(section=>section.id);assert(!sections.includes(descriptor.id));return {profileFamily:'ABSENT',visible:false,sections}},tests);
  run('w4e.family-bound-unknown-family-hidden',()=>{const {owner}=fixture(),descriptor=defineSettingsFamilySectionDescriptor({id:'settings.structured-family-proof',groupId:'settings',label:'Structured family proof',family:'structured',sourceOwner:'W4E_FamilyApplicabilityFixture',items:[{id:'family-proof',label:'Family proof'}]}),sections=owner.sections({family:'unknown-family'},[descriptor]).map(section=>section.id);assert(!sections.includes(descriptor.id));return {profileFamily:'unknown-family',visible:false,sections}},tests);
  run('w4e.family-bound-malformed-family-hidden',()=>{const {owner}=fixture(),descriptor=defineSettingsFamilySectionDescriptor({id:'settings.structured-family-proof',groupId:'settings',label:'Structured family proof',family:'structured',sourceOwner:'W4E_FamilyApplicabilityFixture',items:[{id:'family-proof',label:'Family proof'}]}),malformed={family:{toString(){return 'structured'}}},sections=owner.sections(malformed,[descriptor]).map(section=>section.id);assert(!sections.includes(descriptor.id));assert(!sections.includes('preferences.editor'));return {profileFamilyType:typeof malformed.family,visible:false,editorOnlyVisible:false,sections}},tests);
  run('w4e.global-descriptor-family-absent-follows-global-contract',()=>{const {owner}=fixture(),sections=owner.sections({},[]).map(section=>section.id);assert(sections.includes('settings.general')&&sections.includes('settings.layout')&&sections.includes('commands.catalog')&&sections.includes('shortcuts.global'));return {profileFamily:'ABSENT',visibleGlobalSections:sections}},tests);
  run('w4e.editor-only-hidden-with-absent-family',()=>{const {owner,editorDescriptor}=fixture(),groups=owner.groups({},[editorDescriptor]),labels=groups.map(group=>group.label),sections=groups.flatMap(group=>group.sections.map(section=>section.id));assert(!labels.includes('Editor Shortcuts'));assert(!sections.includes('preferences.editor'));assert(!sections.includes(editorDescriptor.id));return {labels,sections}},tests);
  run('w4e.editor-only-hidden-operational',()=>{const {owner,editorDescriptor}=fixture(),profile={family:'operational',capabilities:{structuredEditor:false}},groups=owner.groups(profile,[editorDescriptor]),labels=groups.map(group=>group.label),sections=groups.flatMap(group=>group.sections.map(section=>section.id));assert(!labels.includes('Editor Shortcuts'));assert(!sections.includes('preferences.editor'));assert(!sections.includes(editorDescriptor.id));return {labels,sections}},tests);
  run('w4e.one-open-accordion',()=>{const {owner,profile,editorDescriptor}=fixture(),ids=owner.sections(profile,[editorDescriptor]).map(section=>section.id);owner.toggleSection(ids[0],profile,[editorDescriptor]);assert(owner.presentation.openSectionId===ids[0]);owner.toggleSection(ids[1],profile,[editorDescriptor]);assert(owner.presentation.openSectionId===ids[1]);owner.toggleSection(ids[1],profile,[editorDescriptor]);assert(owner.presentation.openSectionId===null);return ids.slice(0,2)},tests);
  run('w4e.deterministic-search',()=>{const {owner,profile,editorDescriptor}=fixture(),a=owner.search('ctrl',profile,[editorDescriptor]),b=owner.search('  CTRL  ',profile,[editorDescriptor]);assert(same(a,b));assert(a.length>=3&&a.every(row=>row.matchText.includes('ctrl')));return a.map(row=>row.id)},tests);
  run('w4e.search-arabic-normalization',()=>{assert(normalizeSettingsSearchText('مُحَرِّر ـ عربي')===normalizeSettingsSearchText('محرر عربي'));const fake=[{id:'s',groupId:'settings',groupLabel:'Settings',groupOrder:1,label:'اتجاه المحرر',order:1,sourceOwner:'fixture',items:[{id:'i',kind:'descriptor',label:'مُحَرِّر عربي',sourceOwner:'fixture'}]}],rows=searchSettingsSections(fake,'محرر عربي');assert(rows.length===1);return rows[0].id},tests);
  run('w4e.arrow-navigation-wraps',()=>{const {owner,profile,editorDescriptor}=fixture(),ids=owner.sections(profile,[editorDescriptor]).map(section=>section.id);owner.presentation.focusedSectionId=ids[0];let e=event('ArrowDown'),result=owner.handleDisclosureKey(e,profile,[editorDescriptor]);assert(result.focusSectionId===ids[1]&&e.prevented&&e.stopped);owner.presentation.focusedSectionId=ids[0];e=event('ArrowUp');result=owner.handleDisclosureKey(e,profile,[editorDescriptor]);assert(result.focusSectionId===ids.at(-1));return {first:ids[0],next:ids[1],previousWrap:ids.at(-1)}},tests);
  run('w4e.home-end-navigation',()=>{const {owner,profile,editorDescriptor}=fixture(),ids=owner.sections(profile,[editorDescriptor]).map(section=>section.id);owner.presentation.focusedSectionId=ids[2];let result=owner.handleDisclosureKey(event('End'),profile,[editorDescriptor]);assert(result.focusSectionId===ids.at(-1));result=owner.handleDisclosureKey(event('Home'),profile,[editorDescriptor]);assert(result.focusSectionId===ids[0]);return {first:ids[0],last:ids.at(-1)}},tests);
  run('w4e.keyboard-disclosure-enter-space',()=>{const {owner,profile,editorDescriptor}=fixture(),ids=owner.sections(profile,[editorDescriptor]).map(section=>section.id);owner.presentation.focusedSectionId=ids[0];let result=owner.handleDisclosureKey(event('Enter'),profile,[editorDescriptor]);assert(result.openSectionId===ids[0]);owner.handleDisclosureKey(event('ArrowDown'),profile,[editorDescriptor]);result=owner.handleDisclosureKey(event(' '),profile,[editorDescriptor]);assert(result.openSectionId===ids[1]&&owner.presentation.openSectionId===ids[1]);return result},tests);
  run('w4e.focus-return-delegates-transient-owner',()=>{const {owner,profile,editorDescriptor,transientFocus}=fixture();let focusCount=0;const invoker={focus(){focusCount+=1},isConnected:true,disabled:false,getAttribute(){return null}};owner.open(invoker,{profile,familySections:[editorDescriptor]});assert(transientFocus.top()?.id==='global.settings-center');const receipt=owner.close('test-close');assert(receipt.closed&&receipt.focusReturnOwner==='TransientFocusOwner'&&focusCount===1);assert(transientFocus.lastDismissal?.focusTargetKind==='invoker'&&transientFocus.lastDismissal?.restored===true);return transientFocus.lastDismissal},tests);
  run('w4e.profile-applicability-refuses-hidden-section',()=>{const {owner,profile,editorDescriptor}=fixture({family:'spatial',surface:'enterprise'});throws(()=>owner.toggleSection('editor-shortcuts.structured',profile,[editorDescriptor]),'SETTINGS_SECTION_NOT_APPLICABLE');return owner.groups(profile,[editorDescriptor]).map(group=>group.id)},tests);
  run('w4e.no-hidden-preference-store-live-delegation',()=>{const {owner,preferences,profile,editorDescriptor}=fixture();assert(owner.overrides===undefined&&owner.storage===undefined&&owner.set===undefined&&owner.reset===undefined&&owner.save===undefined);const before=owner.sections(profile,[editorDescriptor]).find(section=>section.id==='settings.layout').items.find(item=>item.key==='chromeDirection').value;preferences.set('chromeDirection','ltr','global');const after=owner.sections(profile,[editorDescriptor]).find(section=>section.id==='settings.layout').items.find(item=>item.key==='chromeDirection').value;assert(before==='auto'&&after==='ltr');return {before,after,valueOwner:'ScopedPreferencesOwner'}},tests);
  run('w4e.no-command-semantics-owner',()=>{const {owner,commands,profile,editorDescriptor}=fixture();assert(owner.execute===undefined&&owner.register===undefined&&owner.registerCommand===undefined);const before=commands.receipts.length;const section=owner.sections(profile,[editorDescriptor]).find(value=>value.id==='commands.catalog');assert(section.items.some(item=>item.commandId==='workspace.search'));assert(commands.receipts.length===before);return {commandCount:section.items.length,receipts:commands.receipts.length}},tests);
  run('w4e.no-duplicate-shortcut-owner',()=>{const {owner,profile,editorDescriptor}=fixture(),sections=owner.sections(profile,[editorDescriptor]),global=sections.find(section=>section.id==='shortcuts.global'),editor=sections.find(section=>section.id==='editor-shortcuts.structured');assert(global.sourceOwner==='GlobalInputKeymapOwner'&&global.items.every(item=>item.shortcutOwner==='GlobalInputKeymapOwner'));assert(editor.sourceOwner==='W4E_BoundedStructuredDescriptorFixture'&&editor.items.every(item=>item.sourceOwner==='W4E_BoundedStructuredDescriptorFixture'));assert(owner.bindings===undefined&&owner.shortcutMap===undefined);return {globalSource:global.sourceOwner,editorSource:editor.sourceOwner}},tests);
  run('w4e.untrusted-family-descriptor-rejected',()=>{const {owner,profile}=fixture();throws(()=>owner.sections(profile,[{id:'bad',groupId:'editor-shortcuts',items:[]}]),'UNTRUSTED_SETTINGS_FAMILY_SECTION_DESCRIPTOR')},tests);
  run('w4e.library-real-consumer-nonmutation',()=>{const library=createStructuredConsumerAdapter('library',{STRUCTURE_TREE,FIXTURES,NOTE_FIXTURES,initialDocumentId:'KU-D05-0021'}),before=JSON.stringify(library.snapshot()),{owner,profile,editorDescriptor}=fixture({family:'structured',surface:'library'}),projection=owner.snapshot(profile,[editorDescriptor]),after=JSON.stringify(library.snapshot());assert(before===after&&projection.groups.some(group=>group.label==='Editor Shortcuts'));return {domainKind:library.domainKind,documentId:library.snapshot().id,groupCount:projection.groups.length}},tests);
  run('w4e.enterprise-real-consumer-nonmutation',()=>{const enterprise=createEnterpriseAdapter(),before=JSON.stringify(enterprise.project()),{owner,profile,editorDescriptor}=fixture({family:'spatial',surface:'enterprise'}),projection=owner.snapshot(profile,[editorDescriptor]),after=JSON.stringify(enterprise.project());assert(before===after&&!projection.groups.some(group=>group.label==='Editor Shortcuts'));return {owner:enterprise.owner,relationCount:enterprise.project().length,groups:projection.groups.map(group=>group.label)}},tests);
  run('w4e.rtl-presentation-from-preference-authority',()=>{const {owner}=fixture(),direction=owner.direction();assert(direction==='rtl');return direction},tests);
  run('w4e.ltr-presentation-reflects-live-preferences',()=>{const {owner,preferences}=fixture();preferences.set('locale','en','global');assert(owner.direction()==='ltr');preferences.set('chromeDirection','rtl','global');assert(owner.direction()==='rtl');preferences.set('chromeDirection','ltr','global');assert(owner.direction()==='ltr');return owner.direction()},tests);
  run('w4e.render-accessible-disclosure-markup',()=>{const {owner,profile,editorDescriptor}=fixture();owner.open(null,{profile,familySections:[editorDescriptor]});const first=owner.sections(profile,[editorDescriptor])[0].id;owner.toggleSection(first,profile,[editorDescriptor]);const html=owner.render(profile,[editorDescriptor]);assert(/role="dialog"/.test(html)&&/aria-modal="true"/.test(html)&&/data-settings-disclosure=/.test(html)&&/aria-expanded="true"/.test(html)&&/role="region"/.test(html)&&/dir="rtl"/.test(html));return {bytes:html.length,firstOpen:first}},tests);
  run('w4e.central-catalog-settings-order',()=>{const settings=SETTINGS_CENTER_SECTION_CATALOG.filter(section=>section.groupId==='settings').map(section=>`${section.order}:${section.id}:${section.label}`);assert(same(settings,['10:settings.general:General','20:settings.layout:Layout']));assert(same(SETTINGS_CENTER_GROUPS.map(group=>group.label),['Preferences','Settings','Commands','Editor Shortcuts','Shortcuts']));return settings},tests);
  run('w4e.descriptor-contract-not-ownership-transfer',()=>{const {editorDescriptor}=fixture();assert(editorDescriptor.contract===SETTINGS_CENTER_SECTION_DESCRIPTOR_CONTRACT&&editorDescriptor.contract.stateClass==='PRESENTATION_DESCRIPTOR_ONLY');assert(editorDescriptor.sourceOwner==='W4E_BoundedStructuredDescriptorFixture');return {contract:editorDescriptor.contract.id,sourceOwner:editorDescriptor.sourceOwner}},tests);
  const pass=tests.filter(test=>test.status==='PASS').length,fail=tests.length-pass;
  return {schemaVersion:1,mission:'W4-E-SETTINGS-CENTER',status:fail?'FAIL':'PASS',total:tests.length,pass,fail,tests};
}
